def next_id(fecha_compra=None):
    # Determinar año de compra para el prefijo
    year = datetime.now().year % 100
    if fecha_compra:
        try:
            for fmt in ['%d-%m-%Y','%Y-%m-%d','%d/%m/%Y']:
                try:
                    year = datetime.strptime(str(fecha_compra)[:10], fmt).year % 100
                    break
                except: pass
        except: pass
    # Correlativo GLOBAL — buscar el mayor en TODOS los activos AF-XX-XXXX
    rows = db_fetchall("SELECT id FROM activos WHERE id LIKE ?", ('AF-%',))
    nums = []
    for r in rows:
        try:
            parts = str(r['id']).split('-')
            if len(parts) >= 3:
                nums.append(int(parts[-1]))
        except: pass
    nxt = max(nums) + 1 if nums else 1000
    return f"AF-{year:02d}-{nxt}"

def login_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user' not in session: return redirect('/login')
        return f(*args, **kwargs)
    return decorated

def admin_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user' not in session:
            if request.path.startswith('/api/'):
                return jsonify({'ok':False,'error':'Sesión expirada, recarga la página'}), 401
            return redirect('/login')
        if session.get('rol') != 'admin':
            return jsonify({'error':'Sin permisos'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/activos/<id>/factor-cm', methods=['POST'])
@admin_required
def actualizar_factor_cm(id):
    data = request.json or {}
    factor = data.get('factor')
    if factor is None:
        db_execute("UPDATE activos SET factor_cm_manual=NULL WHERE id=?", (id,))
        return jsonify({'ok': True, 'fuente': 'auto'})
    try:
        factor = float(factor)
        if factor <= 0: return jsonify({'error': 'Factor debe ser mayor a 0'}), 400
        db_execute("UPDATE activos SET factor_cm_manual=? WHERE id=?", (factor, id))
        db_execute("INSERT INTO movimientos (activo_id,tipo,descripcion,usuario) VALUES (?,?,?,?)",
                   (id, 'Edición', f'Factor CM actualizado manualmente: {factor}', session['user']))
        return jsonify({'ok': True, 'fuente': 'manual', 'factor': factor})
    except:
        return jsonify({'error': 'Factor inválido'}), 400

