@app.route('/api/activos/<id>', methods=['PUT'])
@admin_required
def editar_activo(id):
    data = request.json
    old = db_fetchone("SELECT * FROM activos WHERE id=?", (id,))
    if not old: return jsonify({'error':'No encontrado'}), 404
    campos = ['tipo','subtipo','marca','modelo','serie','estado','edificio','sala',
              'responsable','fecha_compra','precio','documento','vida_util','observaciones',
              'foto','centro_costo','proveedor']
    updates = {c: data[c] for c in campos if c in data}
    if updates:
        sets = ', '.join(f"{c}=?" for c in updates)
        db_execute(f"UPDATE activos SET {sets} WHERE id=?", list(updates.values())+[id])
    cambios = []
    for c in ['estado','edificio','sala','responsable']:
        if c in data and str(old.get(c,'')) != str(data[c]):
            cambios.append(f"{c}: '{old.get(c)}' → '{data[c]}'")
    if cambios:
        db_execute("INSERT INTO movimientos (activo_id,tipo,descripcion,usuario) VALUES (?,?,?,?)",
                   (id,'Edición',' | '.join(cambios),session['user']))
    return jsonify({'ok': True})

@app.route('/admin/corregir-anios-id')
@admin_required
def corregir_anios_id():
    from datetime import datetime as dt
    resultados = []
    rows = db_fetchall("SELECT id, fecha_compra FROM activos WHERE id LIKE ? ORDER BY id", ('AF-%',))
    cambios = 0
    errores = []

    for r in rows:
        id_actual = r['id']
        fecha = r['fecha_compra']
        if not fecha:
            continue
        parts = id_actual.split('-')
        if len(parts) != 3:
            continue
        correlativo = parts[2]

        anio_correcto = None
        for fmt in ['%d-%m-%Y','%Y-%m-%d','%d/%m/%Y']:
            try:
                anio_correcto = dt.strptime(str(fecha)[:10], fmt).year % 100
                break
            except: pass
        if anio_correcto is None:
            errores.append(f"{id_actual}: fecha '{fecha}' no se pudo parsear")
            continue

        nuevo_id = f"AF-{anio_correcto:02d}-{correlativo}"
        if nuevo_id != id_actual:
            try:
                conn, mode = get_db()
                cur = conn.cursor()
                if mode == 'pg':
                    cur.execute("UPDATE activos SET id=%s WHERE id=%s", (nuevo_id, id_actual))
                    cur.execute("UPDATE movimientos SET activo_id=%s WHERE activo_id=%s", (nuevo_id, id_actual))
                else:
                    cur.execute("UPDATE activos SET id=? WHERE id=?", (nuevo_id, id_actual))
                    cur.execute("UPDATE movimientos SET activo_id=? WHERE activo_id=?", (nuevo_id, id_actual))
                conn.commit()
                conn.close()
                resultados.append(f"{id_actual} → {nuevo_id} (fecha: {fecha})")
                cambios += 1
            except Exception as e:
                errores.append(f"{id_actual}: Error al actualizar — {e}")

    html = f"<h3>✅ Corrección de años en IDs completada</h3>"
    html += f"<p><strong>{cambios} activos corregidos</strong> de {len(rows)} revisados</p>"
    if resultados:
        html += "<h4>Cambios realizados:</h4><ul>"
        for r in resultados:
            html += f"<li>{r}</li>"
        html += "</ul>"
    if errores:
        html += "<h4 style='color:red'>Errores:</h4><ul>"
        for e in errores:
            html += f"<li>{e}</li>"
        html += "</ul>"
    html += '<br><a href="/">Volver al inicio</a>'
    return html

@app.route('/admin/diagnostico-correlativos')
@admin_required
def diagnostico_correlativos():
    rows = db_fetchall("SELECT id, fecha_compra FROM activos WHERE id LIKE ? ORDER BY id", ('AF-%',))
    nums = {}
    duplicados_correlativo = {}
    for r in rows:
        parts = r['id'].split('-')
        if len(parts) != 3:
            continue
        try:
            n = int(parts[2])
        except:
            continue
        nums.setdefault(n, []).append(r['id'])

    html = "<h3>Diagnóstico de correlativos AF-XX-XXXX</h3>"
    html += f"<p>Total activos con formato AF-XX-XXXX: {len(rows)}</p>"

    # Correlativos duplicados (mismo número, distinto año o repetido)
    dup = {n: ids for n, ids in nums.items() if len(ids) > 1}
    if dup:
        html += "<h4 style='color:red'>⚠️ Correlativos duplicados:</h4><ul>"
        for n, ids in sorted(dup.items()):
            html += f"<li>Correlativo {n}: {', '.join(ids)}</li>"
        html += "</ul>"
    else:
        html += "<p>No hay correlativos duplicados.</p>"

    # Saltos en la secuencia (posibles activos perdidos)
    todos = sorted(nums.keys())
    if todos:
        faltantes = [n for n in range(todos[0], todos[-1]+1) if n not in nums]
        if faltantes:
            html += f"<h4 style='color:orange'>Correlativos faltantes en la secuencia ({len(faltantes)}):</h4>"
            html += "<p>" + ", ".join(str(n) for n in faltantes) + "</p>"
            html += "<p><em>Nota: algunos pueden ser normales si nunca existieron (ej. activos eliminados intencionalmente antes). Revisa el historial de movimientos para los más recientes.</em></p>"
        else:
            html += "<p>No hay saltos en la secuencia de correlativos.</p>"

    # Últimos movimientos de tipo Edición/Eliminación (para rastrear qué pasó)
    movs = db_fetchall("SELECT activo_id, tipo, descripcion, usuario, fecha FROM movimientos WHERE tipo IN ('Edición','Eliminación') ORDER BY fecha DESC LIMIT 30")
    html += "<h4>Últimos 30 movimientos de Edición/Eliminación:</h4><ul>"
    for m in movs:
        html += f"<li>{m['fecha']} — {m['activo_id']} — {m['tipo']} — {m['descripcion']} — {m['usuario']}</li>"
    html += "</ul>"

    html += '<br><a href="/">Volver al inicio</a>'
    return html


